 internal static class OwnedPairsAuthorityTests
 {
  const string Anchor="11111111-1111-4111-8111-111111111111",Campaign="22222222-1111-4111-8111-111111111111",Area="0123456789abcdef0123456789abcdef",OtherArea="fedcba9876543210fedcba9876543210";
  static int Main()
  {
   var t=new TestRunner();
   foreach(var selectedCase in new[]{"exploration","combat-rider-first","combat-mount-first","realtime-core","realtime-casting","realtime-charge","native-life-cleanup"}) t.Run("closed inherited native read-only case "+selectedCase,()=>{var f=new Fixture();f.Request.OwnedPairs.Case=selectedCase;f.Request.PersistenceCase=null;f.Request.OwnedPairs.ExpectedNativeWriteCount=0;Valid(f.Request);var a=f.Scope();TestRunner.True(a.MatchesOwnedPairsPlan(true,true),"Exact read-only plan missing.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Sole inherited native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(9),f.Root)!=null,"Read-only native campaign gained a write.");TestRunner.Equal(0,a.OwnedPairsReservationCount,"Read-only plan gained a reservation.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Refused write spent authority.");});
   foreach(var checkpoint in new[]{"multi-exploration-manual","multi-exploration-quick","multi-exploration-auto","multi-rt-debt-manual","multi-tb-debt-manual","zero-mounted-tb-retained-manual","legacy-mounted-pending-tb-manual"})t.Run("source checkpoint exact category and reservation "+checkpoint,()=>{var f=new Fixture();f.Request.PersistenceCase=checkpoint;Valid(f.Request);var a=f.Scope();TestRunner.True(a.ValidateArchiveIdentity(f.Load,f.Root)==null,"Native header enumeration refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Unreserved load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)!=null,"Early output admitted.");Unspent(a);f.Reserve(a);TestRunner.True(a.MatchesOwnedPairsPlan(true,true),"Atomic two-entry plan missing.");TestRunner.Equal(f.Number,a.OwnedPairsOutputNumber,"Observed native number replaced.");TestRunner.True(ReferenceEquals(f.Descriptor,a.OwnedPairsSourceDescriptor),"Native source reference replaced.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)!=null,"Reserved output admitted before the sole load.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Reserved native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)==null,"Reserved native write refused.");using(var lease=a.BeginWrite(f.Write(f.Number),f.Root)){BootstrapVirtualFile.OutputExists=true;lease.Complete();}TestRunner.True(a.MatchesOwnedPairsPlan(true,false),"Settled two-entry plan lost.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Second native load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)!=null,"Second native write admitted.");Reset();});
   foreach(var mutation in new[]{"missing","wrong-family","wrong-case","write2","load0","same-source","duplicate-role","bad-id","missing-roster","foreign-roster","duplicate-roster","Working","other-source-name","area-route","alternate","source-hash","old-permission","unsupported-checkpoint","checkpoint-on-exploration","cold-no-parent"})t.Run("typed request refuses "+mutation,()=>{var f=new Fixture();var r=f.Request;switch(mutation){case "missing":r.OwnedPairs=null;break;case "wrong-family":r.Scenario="fixture-intake";break;case "wrong-case":r.OwnedPairs.Case="anything";break;case "write2":r.OwnedPairs.ExpectedNativeWriteCount=2;break;case "load0":r.OwnedPairs.ExpectedNativeLoadCount=0;break;case "same-source":r.OwnedPairs.SourceRunId=r.RunId;break;case "duplicate-role":r.OwnedPairs.MountAId=r.OwnedPairs.RiderAId;break;case "bad-id":r.OwnedPairs.RiderAId="actor";break;case "missing-roster":r.OwnedPairs.PartyIds=null;break;case "foreign-roster":r.OwnedPairs.PartyIds=r.OwnedPairs.PartyIds.Skip(1).ToArray();break;case "duplicate-roster":r.OwnedPairs.PartyIds=r.OwnedPairs.PartyIds.Concat(new[]{r.OwnedPairs.RiderAId}).ToArray();break;case "Working":r.PersistenceLoad.GameId=Anchor;break;case "other-source-name":r.PersistenceLoad.InternalName="KMC_AUTOMATION_WORKING";break;case "area-route":r.PersistenceAreaTarget=new RuntimeAreaTransitionTarget();break;case "alternate":r.PersistenceAlternate=r.PersistenceLoad;break;case "source-hash":r.PersistenceLoad.Sha256=new string('e',64);break;case "old-permission":r.ManualDerived=new Chunk7ManualDerivedSelection();break;case "unsupported-checkpoint":r.PersistenceCase="multi-area-autosave";break;case "checkpoint-on-exploration":r.OwnedPairs.Case="exploration";break;case "cold-no-parent":r.OwnedPairs.Case="persistence-load";break;}TestRunner.True(r.Validate().Count>0,"Foreign typed fixture admitted.");});
   foreach(var fault in new[]{"request","game","manager","descriptor","token","source","type","name","zero","previous-number","foreign-number","inventory","enumeration","bytes","output"}) t.Run("failed atomic output reservation retains no leaf "+fault,()=>{var f=new Fixture();var a=f.Scope();var r=f.Request;var game=f.Game;var manager=f.Manager;var descriptor=f.Descriptor;var target=f.Load;var number=f.Number;var type=f.Type;var name=f.Name;switch(fault){case "request":r=new Fixture().Request;break;case "game":game=new object();break;case "manager":manager=new object();break;case "descriptor":descriptor=null;break;case "token":r.TransactionToken=new string('9',64);break;case "source":target.GameId=Anchor;break;case "type":type="Quick";break;case "name":name="foreign";break;case "zero":number=0;break;case "previous-number":number--;break;case "foreign-number":number++;break;case "inventory":BootstrapVirtualDirectory.ForeignEntry=true;break;case "enumeration":BootstrapVirtualDirectory.Throw=true;break;case "bytes":BootstrapVirtualStorage.SourceChanged=true;break;case "output":BootstrapVirtualFile.OutputExists=true;break;}Refuses(()=>a.ReserveOwnedPairsOutput(r,game,manager,descriptor,target,number,type,name));Reset();Unspent(a);TestRunner.True(a.OwnedPairsOutputLeaf==null&&a.OwnedPairsSourceDescriptor==null,"Failed reservation retained native write permission.");});
   foreach(var delta in new[]{0,1})t.Run("repeat output reservation refuses "+delta,()=>{var f=new Fixture();var a=f.Scope();f.Reserve(a);Refuses(()=>a.ReserveOwnedPairsOutput(f.Request,f.Game,f.Manager,new object(),f.Load,f.Number+delta,f.Type,f.Name));TestRunner.Equal(f.Number,a.OwnedPairsOutputNumber,"Original reservation replaced.");TestRunner.Equal(1,a.OwnedPairsReservationCount,"Duplicate changed reservation count.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Reservation spent load.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Reservation spent write.");});
   foreach(var mutation in new[]{"token","actor","roster","scenario","source-length"}) foreach(var boundary in new[]{"validate-load","authorize-load","archive-identity","authorize-write","storage"}) t.Run("captured request mutation refuses later "+mutation+" "+boundary,()=>{var f=new Fixture();var a=f.Scope();f.Reserve(a);if(boundary=="authorize-write"||boundary=="storage"){TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Setup load failed.");if(boundary=="storage")TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(f.Number),f.Root)==null,"Setup write failed.");}var load=f.Load;var write=f.Write(f.Number);var loads=a.AdmittedNativeLoadRequests;var writes=a.AdmittedNativeWriteRequests;switch(mutation){case "token":f.Request.TransactionToken=new string('9',64);break;case "actor":f.Request.OwnedPairs.RiderAId="99999999-1111-4111-8111-111111111111";break;case "roster":Array.Reverse(f.Request.OwnedPairs.PartyIds);break;case "scenario":f.Request.Scenario="fixture-intake";break;case "source-length":f.Request.PersistenceLoad.Length++;break;}if(boundary=="storage")Refuses(()=>{using(a.BeginWrite(write,f.Root)){} });else TestRunner.True((boundary=="validate-load"?a.Validate(RuntimeSaveOperation.Load,load,f.Root):boundary=="archive-identity"?a.ValidateArchiveIdentity(load,f.Root):a.AuthorizeNativeRequest(boundary=="authorize-write"?RuntimeSaveOperation.Write:RuntimeSaveOperation.Load,boundary=="authorize-write"?write:load,f.Root))!=null,"Changed captured request admitted.");TestRunner.True(!a.MatchesOwnedPairsPlan(true,false),"Changed captured request matched plan.");TestRunner.Equal(loads,a.AdmittedNativeLoadRequests,"Refusal spent load.");TestRunner.Equal(writes,a.AdmittedNativeWriteRequests,"Refusal spent write.");TestRunner.Equal(1,a.OwnedPairsReservationCount,"Refusal changed exact reservation.");});
   t.Run("historical authority has no inherited reservation",()=>{var f=new Fixture();var a=f.Scope(false);Refuses(()=>f.Reserve(a));TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Historical immutable source admission changed.");});

   foreach(var areas in new[]{false,true})t.Run("closed owned replay immutable load quota "+areas,()=>{var f=Replay(areas);Valid(f.Request);var a=f.Scope();TestRunner.True(a.MatchesOwnedPairsPlan(true,true),"Closed replay source plan missing.");for(var i=0;i<f.Request.OwnedPairs.ExpectedNativeLoadCount;i++){TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Selected next load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Selected next actual load refused.");}TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"One extra native load admitted.");TestRunner.Equal(areas?1:3,a.AdmittedNativeLoadRequests,"Refused extra load changed count.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(9),f.Root)!=null,"Replay gained a native write.");Unreserved(a);});
   foreach(var areas in new[]{false,true})foreach(var count in new[]{0,1,2,3,4})if(count!=(areas?1:3))t.Run("replay quota mismatch "+areas+" "+count,()=>{var f=Replay(areas);f.Request.OwnedPairs.ExpectedNativeLoadCount=count;TestRunner.True(f.Request.Validate().Count>0,"Declared replay quota expanded or shrank.");Refuses(()=>f.Scope());});
   foreach(var caseName in new[]{"multi-exploration-three-loads-manual","multi-exploration-three-area-transfers-manual"})t.Run("replay source save alias refuses "+caseName,()=>{var f=new Fixture();f.Request.PersistenceCase=caseName;TestRunner.True(f.Request.Validate().Count>0,"Save source gained replay alias.");});
   foreach(var change in new[]{"case","selection","count","route-area","route-entry","route-mode","route-order","route-null","token","actor"})foreach(var boundary in new[]{"validate","admit","identity"})t.Run("closed replay later mutation refuses "+change+" "+boundary,()=>{var f=Replay(true);var a=f.Scope();switch(change){case "case":f.Request.PersistenceCase="multi-exploration-three-loads-manual";f.Request.PersistenceReplayTargets=null;f.Request.OwnedPairs.ExpectedNativeLoadCount=3;break;case "selection":f.Request.OwnedPairs.Case="persistence-save";break;case "count":f.Request.OwnedPairs.ExpectedNativeLoadCount=3;break;case "route-area":f.Request.PersistenceReplayTargets[0].Area=new string('a',32);break;case "route-entry":f.Request.PersistenceReplayTargets[0].EnterPoint=new string('b',32);break;case "route-mode":f.Request.PersistenceReplayTargets[0].AutoSaveMode="BeforeExit";break;case "route-order":Array.Reverse(f.Request.PersistenceReplayTargets);break;case "route-null":f.Request.PersistenceReplayTargets=null;break;case "token":f.Request.TransactionToken=new string('9',64);break;case "actor":f.Request.OwnedPairs.RiderAId="99999999-1111-4111-8111-111111111111";break;}TestRunner.True((boundary=="validate"?a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root):boundary=="identity"?a.ValidateArchiveIdentity(f.Load,f.Root):a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root))!=null,"Changed captured replay admitted.");TestRunner.True(!a.MatchesOwnedPairsPlan(true,false),"Changed replay matched original plan.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Refusal spent native load.");Unreserved(a);});
   foreach(var change in new[]{"same-loaded-area","too-few","null-target","wrong-mode","route-on-loads"})t.Run("owned replay route pre-admission "+change,()=>{var f=Replay(true);switch(change){case "same-loaded-area":f.Request.PersistenceReplayTargets[0].Area=Area;break;case "too-few":f.Request.PersistenceReplayTargets=f.Request.PersistenceReplayTargets.Take(2).ToArray();break;case "null-target":f.Request.PersistenceReplayTargets[0]=null;break;case "wrong-mode":f.Request.PersistenceReplayTargets[0].AutoSaveMode="AfterEntry";break;case "route-on-loads":f.Request.PersistenceCase="multi-exploration-three-loads-manual";f.Request.OwnedPairs.ExpectedNativeLoadCount=3;break;}TestRunner.True(f.Request.Validate().Count>0,"Unqualified route admitted.");});
   return t.Complete();
  }

  static void Unreserved(PersistenceSaveAuthorization a){TestRunner.Equal(0,a.OwnedPairsReservationCount,"Replay reserved a writable leaf.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Replay spent a native write.");TestRunner.True(a.OwnedPairsOutputLeaf==null,"Replay retained an output.");}
  static Fixture Replay(bool area){var f=new Fixture();f.Request.OwnedPairs.Case="persistence-load";f.Request.OwnedPairs.CheckpointSourceRunId="completed-owned-checkpoint";f.Request.OwnedPairs.CheckpointSourceArtifactSha256=new string('8',64);f.Request.OwnedPairs.ExpectedNativeLoadCount=area?1:3;f.Request.OwnedPairs.ExpectedNativeWriteCount=0;f.Request.PersistenceCase=area?"multi-exploration-three-area-transfers-manual":"multi-exploration-three-loads-manual";f.Request.PersistenceLoad.InternalName="KMC_C7_WORLD";f.Request.PersistenceLoad.FileName="Manual_9_KMC_C7_WORLD.zks";if(area)f.Request.PersistenceReplayTargets=new[]{new RuntimeAreaTransitionTarget{EnterPoint=new string('1',32),Area=OtherArea,AutoSaveMode="None"},new RuntimeAreaTransitionTarget{EnterPoint=new string('2',32),Area=Area,AutoSaveMode="None"},new RuntimeAreaTransitionTarget{EnterPoint=new string('3',32),Area=OtherArea,AutoSaveMode="None"}};return f;}
  static void Valid(RuntimeRequest request){TestRunner.Equal(0,request.Validate().Count,string.Join(" | ",request.Validate()));}
  static void Refuses(Action action){bool refused=false;try{action();}catch(ArgumentException){refused=true;}catch(InvalidOperationException){refused=true;}catch(System.IO.IOException){refused=true;}TestRunner.True(refused,"Expected exact authority refusal.");}
  static void Reset(){BootstrapVirtualDirectory.ForeignEntry=false;BootstrapVirtualDirectory.Throw=false;BootstrapVirtualStorage.SourceChanged=false;BootstrapVirtualFile.OutputExists=false;}
  static void Unspent(PersistenceSaveAuthorization a){TestRunner.Equal(0,a.OwnedPairsReservationCount,"Refusal reserved output.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Refusal spent load.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Refusal spent write.");}
  static RuntimeSaveDescriptor Descriptor(string n,string f,string h)=>new RuntimeSaveDescriptor{InternalName=n,FileName=f,Sha256=h,Length=10,LastWriteTimeUtcTicks=638907120000000000L,GameId=Anchor,GameName="Anchor",Area=Area};
  sealed class Fixture
  {
   internal const string RunRoot=@"C:\KmcBootstrapVirtual\run";internal readonly string Root=RunRoot+@"\Saved Games";
   internal readonly object Game=new object(),Manager=new object(),Descriptor=new object();
   internal readonly RuntimeRequest Request=new RuntimeRequest{SchemaVersion=2,RunId="acquired-test",Scenario=Chunk7OwnedPairsSelection.Scenario,PersistenceCase="multi-exploration-manual",OwnedPairs=new Chunk7OwnedPairsSelection{Case="persistence-save",SourceRunId="completed-two-owner-manual",SourceArtifactSha256=new string('c',64),SourceArchiveSha256=new string('d',64),RiderAId="44444444-1111-4111-8111-111111111111",MountAId="55555555-1111-4111-8111-111111111111",RiderBId="66666666-1111-4111-8111-111111111111",MountBId="77777777-1111-4111-8111-111111111111",PartyIds=new[]{"44444444-1111-4111-8111-111111111111","55555555-1111-4111-8111-111111111111","66666666-1111-4111-8111-111111111111","77777777-1111-4111-8111-111111111111","88888888-1111-4111-8111-111111111111"},BaseGameOnly=true,ExpectedNativeLoadCount=1,ExpectedNativeWriteCount=1},PersistenceLoad=new RuntimeSaveDescriptor{FileName="Manual_8_KMC_C7_ACQUIRED_FIELD.zks",InternalName="KMC_C7_ACQUIRED_FIELD",Sha256=new string('d',64),Length=10,LastWriteTimeUtcTicks=638907120000000000L,GameId=Campaign,GameName="Native",Area=Area},Branch="codex/mounted-combat-chunk7-foundation",Commit=new string('1',40),ProductVersion=BuildIdentity.ProductVersion,DllSha256=new string('2',64),DllMvid=Anchor,TransactionToken=new string('3',64),EvidenceRoot=@"C:\KmcBootstrapVirtual\evidence",Fixture=new RuntimeFixtureIdentity{Baseline=OwnedPairsAuthorityTests.Descriptor("KMC_AUTOMATION_BASELINE","Manual_298_KMC_AUTOMATION_BASELINE.zks",new string('a',64)),Working=OwnedPairsAuthorityTests.Descriptor("KMC_AUTOMATION_WORKING","Manual_299_KMC_AUTOMATION_WORKING.zks",new string('b',64)),WriteAuthorization=new RuntimeSaveWriteAuthorization{Mode="working-only",AllowedInternalName="KMC_AUTOMATION_WORKING",AllowedFileName="Manual_299_KMC_AUTOMATION_WORKING.zks",BaselineImmutable=true}},QualificationSuite=new RuntimeQualificationSuiteIdentity{SuiteId="bootstrap-suite",SnapshotSha256=new string('4',64)}};
   internal RuntimeSaveTarget Load=>new RuntimeSaveTarget{InternalName=Request.PersistenceLoad.InternalName,FileName=Request.PersistenceLoad.FileName,FullPath=Root+"\\"+Request.PersistenceLoad.FileName,SaveType=Request.ExpectedNativeLoadType,GameId=Campaign,GameName="Native",Area=Area};
   internal string Type=>Request.OwnedPairs.Cold?"Manual":Request.PersistenceCase=="multi-exploration-quick"?"Quick":Request.PersistenceCase=="multi-exploration-auto"?"Auto":"Manual";
   internal string Name=>Request.OwnedPairs.Cold?"KMC_C7_SCHEMA2":Type=="Manual"?"KMC_C7_WORLD":Type=="Quick"?"Quicksave":"Autosave";
   internal int Number=>Type=="Manual"?9:1;
   internal RuntimeSaveTarget Write(int n)=>new RuntimeSaveTarget{InternalName=Name,FileName=Type+"_"+n+(Type=="Manual"?"_"+Name:"")+".zks",FullPath=Root+"\\"+Type+"_"+n+(Type=="Manual"?"_"+Name:"")+".zks",SaveType=Type,GameId=Campaign,GameName="Native",Area=Area};
   internal PersistenceSaveEntry[] Entries()=>new[]{new PersistenceSaveEntry{FileName=Request.PersistenceLoad.FileName,InternalName=Request.PersistenceLoad.InternalName,SaveType=Request.ExpectedNativeLoadType,Area=Area,InitialSha256=new string('d',64)}};
   internal PersistenceSaveAuthorization Scope(bool selected=true){Reset();BootstrapVirtualStorage.InputLeaf=Request.PersistenceLoad.FileName;return new PersistenceSaveAuthorization(RunRoot,Campaign,"Native",new string('a',64),Entries(),null,null,selected?(int?)Request.OwnedPairs.ExpectedNativeWriteCount:1,selected?(int?)Request.OwnedPairs.ExpectedNativeLoadCount:1,null,null,null,selected?Request:null,selected?Game:null,selected?Manager:null,selected&&Request.OwnedPairs.ExpectedNativeWriteCount==1?Name:null);}
   internal void Reserve(PersistenceSaveAuthorization scope)=>scope.ReserveOwnedPairsOutput(Request,Game,Manager,Descriptor,Load,Number,Type,Name);
  }
 }
 internal static class BootstrapVirtualDirectory {internal static bool ForeignEntry,Throw;internal static IEnumerable<string> EnumerateFileSystemEntries(string path){if(Throw)throw new System.IO.IOException("enumeration failed");return ForeignEntry?new[]{path+"\\"+BootstrapVirtualStorage.InputLeaf,path+@"\foreign.zks"}:new[]{path+"\\"+BootstrapVirtualStorage.InputLeaf};}internal static bool Exists(string path)=>!path.EndsWith(".zks",StringComparison.Ordinal);}
 internal static class BootstrapVirtualFile {internal static bool OutputExists;internal static bool Exists(string path)=>path.EndsWith(BootstrapVirtualStorage.InputLeaf,StringComparison.Ordinal)||OutputExists;internal static void Delete(string path){throw new InvalidOperationException("Unexpected filesystem mutation.");}}
 internal static class BootstrapVirtualStorage {internal static string InputLeaf="Manual_8_KMC_C7_ACQUIRED_FIELD.zks";internal static bool SourceChanged;internal static void RequireDirectory(string path){if(string.IsNullOrEmpty(path))throw new InvalidOperationException();}internal static string Hash(string path)=>new string(path.EndsWith(InputLeaf,StringComparison.Ordinal)?(SourceChanged?'e':'d'):'f',64);}
